// Acessa o array de campanhas
const campaigns = $json.data; // Certifique-se de que "data" contém suas campanhas
const results = [];

// Loop para verificar cada campanha
for (const campaign of campaigns) {
    // Verifica se "campaign_name" contém "[TOFU]"
    if (campaign.campaign_name && campaign.campaign_name.includes($node["Loop Over Items"].json["Filtro 2"])) {
        results.push({
            ...campaign,
            containsTOFU: true // Adiciona um novo campo se a palavra for encontrada
        });
    }
}

// Retorna os resultados
return results.length > 0 ? results : [{ message: "Nenhuma campanha foi encontrada." }];

const input = $item("0").$node["Aggregate3"].json["data"];

const transformData = (data) => {
    // Verificar se data é um array válido
    if (!Array.isArray(data)) {
        return [];
    }

    // Estrutura para armazenar dados agregados
    const campaigns = {};
    const allAds = [];

    // Processa cada item
    data.forEach(item => {
        if (!item) return;

        const campaignName = item.campaign_name || "";
        const adsetName = item.adset_name || "";
        const adName = item.ad_name || "";
        const spend = parseFloat(item.spend) || 0;

        // Verifica se é campanha de alcance
        const isReachCampaign = (
            campaignName.toLowerCase().includes('alcance') ||
            adsetName.toLowerCase().includes('alcance') ||
            adName.toLowerCase().includes('alcance')
        );

        // Declara leads aqui para estar disponível em todos os escopos
        let leads = 0;

        // Se for campanha de alcance, usa métricas de alcance
        if (isReachCampaign) {
            const reach = parseInt(item.reach) || 0;
            leads = reach; // Usa reach como "leads" para manter a estrutura

            if (reach > 0) {
                allAds.push({
                    campaign_name: campaignName,
                    adset_name: adsetName,
                    ad_name: adName,
                    spend: spend,
                    leads: reach,
                    cpl: spend / reach, // CPM efetivo (custo por pessoa alcançada)
                    tipo_metrica: "alcance"
                });
            }
        } else {
            // Busca por leads nas actions (lógica original)
            if (item.actions && Array.isArray(item.actions)) {
                // Primeiro tenta encontrar "lead" (mantém a lógica original)
                let leadAction = item.actions.find(action => 
                    action && action.action_type === "lead"
                );

                // Se não encontrou "lead", busca por conversões de mensagens
                if (!leadAction) {
                    // Define os tipos de conversão de mensagens aceitos
                    const messageConversionTypes = [
                        "onsite_conversion.messaging_conversation_started_7d",
                        "onsite_conversion.total_messaging_connection",
                        "onsite_conversion.messaging_first_reply"
                    ];

                    // Busca por qualquer tipo de conversão de mensagem
                    leadAction = item.actions.find(action => 
                        action && messageConversionTypes.includes(action.action_type)
                    );
                }

                // Se encontrou qualquer tipo de lead/conversão
                if (leadAction) {
                    leads = parseInt(leadAction.value) || 0;
                }
            }

            // Armazena CADA ocorrência do anúncio (não agregado)
            if (leads > 0) { // Só adiciona se tiver leads
                allAds.push({
                    campaign_name: campaignName,
                    adset_name: adsetName,
                    ad_name: adName,
                    spend: spend,
                    leads: leads,
                    cpl: spend / leads,
                    tipo_metrica: "leads"
                });
            }
        }

        // Inicializa estrutura da campanha se não existir
        if (!campaigns[campaignName]) {
            campaigns[campaignName] = {
                adsets: {},
                totalSpend: 0,
                totalLeads: 0,
                tipo_metrica: isReachCampaign ? "alcance" : "leads"
            };
        }

        // Inicializa conjunto de anúncios se não existir
        if (!campaigns[campaignName].adsets[adsetName]) {
            campaigns[campaignName].adsets[adsetName] = {
                spend: 0,
                leads: 0
            };
        }

        // Acumula valores - para alcance usa reach, para outros usa leads
        const valueToAccumulate = isReachCampaign ? (parseInt(item.reach) || 0) : leads;
        campaigns[campaignName].adsets[adsetName].spend += spend;
        campaigns[campaignName].adsets[adsetName].leads += valueToAccumulate;
        campaigns[campaignName].totalSpend += spend;
        campaigns[campaignName].totalLeads += valueToAccumulate;
    });

    // Gera array de resultados formatados
    const results = [];
    let campaignIndex = 1;

    Object.keys(campaigns).forEach(campaignName => {
        const campaign = campaigns[campaignName];
        const isReachCampaign = campaign.tipo_metrica === "alcance";

        // Adiciona header da campanha
        results.push({
            tipo: "header_campanha",
            texto: `Campanha ${campaignIndex}: ${campaignName}`
        });

        // Adiciona conjuntos de anúncios
        let adsetIndex = 1;
        Object.keys(campaign.adsets).forEach(adsetName => {
            const adset = campaign.adsets[adsetName];
            const cpl = adset.leads > 0 ? (adset.spend / adset.leads) : 0;

            if (isReachCampaign) {
                results.push({
                    tipo: "conjunto_anuncio",
                    numero: adsetIndex,
                    nome: adsetName,
                    investimento: adset.spend,
                    investimento_formatado: `R$ ${adset.spend.toFixed(2).replace('.', ',')}`,
                    alcance: adset.leads,
                    custo_por_alcance: cpl,
                    custo_por_alcance_formatado: `R$ ${cpl.toFixed(2).replace('.', ',')}`,
                    tipo_metrica: "alcance",
                    label_metrica: "pessoas_alcancadas"
                });
            } else {
                results.push({
                    tipo: "conjunto_anuncio",
                    numero: adsetIndex,
                    nome: adsetName,
                    investimento: adset.spend,
                    investimento_formatado: `R$ ${adset.spend.toFixed(2).replace('.', ',')}`,
                    leads: adset.leads,
                    custo_por_lead: cpl,
                    custo_por_lead_formatado: `R$ ${cpl.toFixed(2).replace('.', ',')}`,
                    tipo_metrica: "leads",
                    label_metrica: "leads"
                });
            }

            adsetIndex++;
        });

        // Adiciona totais
        const avgCpl = campaign.totalLeads > 0 ? (campaign.totalSpend / campaign.totalLeads) : 0;

        if (isReachCampaign) {
            results.push({
                tipo: "total",
                investimento_total: campaign.totalSpend,
                investimento_formatado: `R$ ${campaign.totalSpend.toFixed(2).replace('.', ',')}`,
                alcance_total: campaign.totalLeads,
                custo_medio_por_alcance: avgCpl,
                custo_medio_formatado: `R$ ${avgCpl.toFixed(2).replace('.', ',')}`,
                tipo_metrica: "alcance",
                label_metrica: "pessoas_alcancadas_total"
            });
        } else {
            results.push({
                tipo: "total",
                investimento_total: campaign.totalSpend,
                investimento_formatado: `R$ ${campaign.totalSpend.toFixed(2).replace('.', ',')}`,
                leads_total: campaign.totalLeads,
                custo_medio_por_lead: avgCpl,
                custo_medio_formatado: `R$ ${avgCpl.toFixed(2).replace('.', ',')}`,
                tipo_metrica: "leads",
                label_metrica: "leads_total"
            });
        }

        // Encontra melhor criativo (menor CPL entre os que têm leads)
        let bestAd = null;
        allAds.forEach(ad => {
            if (ad.campaign_name === campaignName) {
                if (!bestAd || ad.cpl < bestAd.cpl) {
                    bestAd = ad;
                }
            }
        });

        // Adiciona melhor criativo
        if (bestAd) {
            if (isReachCampaign) {
                results.push({
                    tipo: "melhor_criativo",
                    nome: bestAd.ad_name,
                    conjunto_anuncio: bestAd.adset_name,
                    alcance: bestAd.leads,
                    custo_por_alcance: bestAd.cpl,
                    custo_por_alcance_formatado: `R$ ${bestAd.cpl.toFixed(2).replace('.', ',')}`,
                    tipo_metrica: "alcance",
                    label_metrica: "pessoas_alcancadas"
                });
            } else {
                results.push({
                    tipo: "melhor_criativo",
                    nome: bestAd.ad_name,
                    conjunto_anuncio: bestAd.adset_name,
                    leads: bestAd.leads,
                    custo_por_lead: bestAd.cpl,
                    custo_por_lead_formatado: `R$ ${bestAd.cpl.toFixed(2).replace('.', ',')}`,
                    tipo_metrica: "leads",
                    label_metrica: "leads"
                });
            }
        } else {
            results.push({
                tipo: "melhor_criativo",
                mensagem: isReachCampaign ? "Nenhum criativo teve alcance" : "Nenhum criativo gerou leads"
            });
        }

        campaignIndex++;
    });

    return results;
};

// Processa os dados
const result = transformData(input);

// Retorna os dados no formato correto para n8n
return result;

// Obter os dados do input do n8n
const data = $item("0").$node["Aggregate4"].json["data"];
// Verifica se data é um array válido
if (!Array.isArray(data)) {
  throw new Error("O input 'data' não é um array ou está indefinido.");
}

// Função para processar os dados formatados
function processAdsets(data) {
  const adsetsMap = new Map();
  let campaignName = "";
  let isReachCampaign = false;

  // Extrai o nome da campanha do header
  const headerItem = data.find(item => item.tipo === "header_campanha");
  if (headerItem && headerItem.texto) {
    // Extrai o nome da campanha do texto
    const match = headerItem.texto.match(/Campanha \d+: (.+)/);
    if (match) {
      campaignName = match[1];
      // Verifica se é campanha de alcance
      isReachCampaign = campaignName.toLowerCase().includes('alcance');
    }
  }

  // Processa apenas os conjuntos de anúncios
  const conjuntos = data.filter(item => item.tipo === "conjunto_anuncio");

  conjuntos.forEach(item => {
    const adsetName = item.nome;
    const spend = item.investimento || 0;

    // Usa a propriedade correta baseado no tipo de campanha
    const actionsValue = isReachCampaign ? (item.alcance || 0) : (item.leads || 0);

    if (!adsetsMap.has(adsetName)) {
      adsetsMap.set(adsetName, { spend_total: 0, actions_total: 0 });
    }

    const current = adsetsMap.get(adsetName);
    current.spend_total = spend;  // Como já vem agregado, não soma
    current.actions_total = actionsValue;
    adsetsMap.set(adsetName, current);
  });

  // Formatar o resultado
  const result = [];
  adsetsMap.forEach((value, key) => {
    const cpa = value.actions_total > 0 ? (value.spend_total / value.actions_total).toFixed(2) : 0;
    result.push({ adset_name: key, ...value, cpa: parseFloat(cpa) });
  });

  // Busca os dados do total
  const totalItem = data.find(item => item.tipo === "total");
  let total = null;

  if (totalItem) {
    if (isReachCampaign) {
      total = {
        investimento_total: totalItem.investimento_total || 0,
        alcance_total: totalItem.alcance_total || 0,
        custo_medio_por_alcance: totalItem.custo_medio_por_alcance || 0
      };
    } else {
      total = {
        investimento_total: totalItem.investimento_total || 0,
        leads_total: totalItem.leads_total || 0,
        custo_medio_por_lead: totalItem.custo_medio_por_lead || 0
      };
    }
  }

  // Busca os dados do melhor criativo
  const melhorItem = data.find(item => item.tipo === "melhor_criativo");
  let melhor_criativo = null;

  if (melhorItem) {
    if (isReachCampaign) {
      melhor_criativo = {
        nome: melhorItem.nome || "",
        alcance: melhorItem.alcance || 0,
        custo_por_alcance: melhorItem.custo_por_alcance || 0
      };
    } else {
      melhor_criativo = {
        nome: melhorItem.nome || "",
        leads: melhorItem.leads || 0,
        custo_por_lead: melhorItem.custo_por_lead || 0
      };
    }
  }

  return { 
    campaign_name: campaignName, 
    total_unique_adsets: adsetsMap.size, 
    adsets: result,
    total: total,
    melhor_criativo: melhor_criativo,
    tipo_metrica: isReachCampaign ? "alcance" : "leads"
  };
}

// Chamar a função e exibir o resultado
try {
  const result = processAdsets(data);
  console.log(result);
  return result; // Retorna o resultado para uso posterior no fluxo do n8n
} catch (error) {
  console.error("Erro ao processar os dados:", error.message);
  throw error;
}

