// Função para processar os dados formatados
function processAdsets(data) {
  const adsetsMap = new Map();
  let campaignName = "";
  let isReachCampaign = false;

  // Extrai o nome da campanha do header
  const headerItem = data.find(item => item.tipo === "header_campanha");
  if (headerItem && headerItem.texto) {
    // Extrai o nome da campanha do texto
    const match = headerItem.texto.match(/Campanha \d+: (.+)/);
    if (match) {
      campaignName = match[1];
      // Verifica se é campanha de alcance
      isReachCampaign = campaignName.toLowerCase().includes('alcance');
    }
  }

  // Processa apenas os conjuntos de anúncios
  const conjuntos = data.filter(item => item.tipo === "conjunto_anuncio");

  conjuntos.forEach(item => {
    const adsetName = item.nome;
    const spend = item.investimento || 0;

    // Usa a propriedade correta baseado no tipo de campanha
    const actionsValue = isReachCampaign ? (item.alcance || 0) : (item.leads || 0);

    if (!adsetsMap.has(adsetName)) {
      adsetsMap.set(adsetName, { spend_total: 0, actions_total: 0 });
    }

    const current = adsetsMap.get(adsetName);
    current.spend_total = spend;  // Como já vem agregado, não soma
    current.actions_total = actionsValue;
    adsetsMap.set(adsetName, current);
  });

  // Formatar o resultado
  const result = [];
  adsetsMap.forEach((value, key) => {
    const cpa = value.actions_total > 0 ? (value.spend_total / value.actions_total).toFixed(2) : 0;
    result.push({ adset_name: key, ...value, cpa: parseFloat(cpa) });
  });

  // Busca os dados do total
  const totalItem = data.find(item => item.tipo === "total");
  let total = null;

  if (totalItem) {
    if (isReachCampaign) {
      total = {
        investimento_total: totalItem.investimento_total || 0,
        alcance_total: totalItem.alcance_total || 0,
        custo_medio_por_alcance: totalItem.custo_medio_por_alcance || 0
      };
    } else {
      total = {
        investimento_total: totalItem.investimento_total || 0,
        leads_total: totalItem.leads_total || 0,
        custo_medio_por_lead: totalItem.custo_medio_por_lead || 0
      };
    }
  }

  // Busca os dados do melhor criativo
  const melhorItem = data.find(item => item.tipo === "melhor_criativo");
  let melhor_criativo = null;

  if (melhorItem) {
    if (isReachCampaign) {
      melhor_criativo = {
        nome: melhorItem.nome || "",
        alcance: melhorItem.alcance || 0,
        custo_por_alcance: melhorItem.custo_por_alcance || 0
      };
    } else {
      melhor_criativo = {
        nome: melhorItem.nome || "",
        leads: melhorItem.leads || 0,
        custo_por_lead: melhorItem.custo_por_lead || 0
      };
    }
  }

  return { 
    campaign_name: campaignName, 
    total_unique_adsets: adsetsMap.size, 
    adsets: result,
    total: total,
    melhor_criativo: melhor_criativo,
    tipo_metrica: isReachCampaign ? "alcance" : "leads"
  };
}

