// Função para gerar um relatório para TODAS as campanhas
const generateReportForAll = (campaigns) => {
  // Cria um array para armazenar o texto do relatório de cada campanha
  const reportParts = campaigns.map((campaignData, campaignIndex) => {
    // Pega os dados da campanha atual no laço
    const campaignName = campaignData.campaign_name;
    const adsets = campaignData.adsets || [];
    const total = campaignData.total || {};
    const melhorCriativo = campaignData.melhor_criativo || {};

    // Verifica se é campanha de alcance
    const isReachCampaign = campaignName.toLowerCase().includes('alcance');

    // Inicia o relatório para esta campanha
    let report = `*Campanha ${campaignIndex + 1}: ${campaignName}*\n`;

    // Adiciona os conjuntos de anúncios
    adsets.forEach((adset, adsetIndex) => {
      const investimento = (adset.spend_total || 0).toFixed(2).replace('.', ',');
      const actions = adset.actions_total || 0;
      const custoPorAction = (adset.cpa || 0).toFixed(2).replace('.', ',');

      report += `\n*Conjunto de anúncio ${adsetIndex + 1}:* "${adset.adset_name}"\n`;
      report += `• Investimento: R$ ${investimento}\n`;

      if (isReachCampaign) {
        report += `• Alcance: ${actions}\n`;
        report += `• Custo por Alcance: R$ ${custoPorAction}\n`;
      } else {
        report += `• Leads: ${actions}\n`;
        report += `• Custo por Lead: R$ ${custoPorAction}\n`;
      }
    });

    // Adiciona a seção de totais
    const investimentoTotal = (total.investimento_total || 0).toFixed(2).replace('.', ',');

    report += `\n*Total da Campanha*\n`;
    report += `• Investimento: R$ ${investimentoTotal}\n`;

    if (isReachCampaign) {
      const alcanceTotal = total.alcance_total || 0;
      const custoMedio = (total.custo_medio_por_alcance || 0).toFixed(2).replace('.', ',');
      report += `• Alcance total: ${alcanceTotal}\n`;
      report += `• Custo médio por alcance: R$ ${custoMedio}\n`;
    } else {
      const leadsTotal = total.leads_total || 0;
      const custoMedio = (total.custo_medio_por_lead || 0).toFixed(2).replace('.', ',');
      report += `• Leads total: ${leadsTotal}\n`;
      report += `• Custo médio por lead: R$ ${custoMedio}\n`;
    }

    // Adiciona a seção do melhor criativo
    report += `\n🏆 Melhor Criativo da Campanha\n`;

    if (isReachCampaign) {
      if (melhorCriativo.nome && melhorCriativo.alcance > 0) {
        const melhorCusto = (melhorCriativo.custo_por_alcance || 0).toFixed(2).replace('.', ',');
        report += `• Nome: "${melhorCriativo.nome}"\n`;
        report += `• Alcance: ${melhorCriativo.alcance}\n`;
        report += `• Custo por Alcance: R$ ${melhorCusto}`;
      } else {
        report += `• Nenhum criativo teve alcance nesta campanha`;
      }
    } else {
      if (melhorCriativo.nome && melhorCriativo.leads > 0) {
        const melhorCpl = (melhorCriativo.custo_por_lead || 0).toFixed(2).replace('.', ',');
        report += `• Nome: "${melhorCriativo.nome}"\n`;
        report += `• Leads: ${melhorCriativo.leads}\n`;
        report += `• Custo por Lead: R$ ${melhorCpl}`;
      } else {
        report += `• Nenhum criativo gerou leads nesta campanha`;
      }
    }

    // Retorna o texto do relatório para esta campanha
    return report;
  });

  // Une os relatórios de todas as campanhas com um separador para melhor leitura
  return reportParts.join('\n\n--------------------------------------\n\n');
};

