const input = $item("0").$node["Aggregate"].json["data"];

const transformData = (data) => {
    // Verificar se data é um array válido
    if (!Array.isArray(data)) {
        return [];
    }

    // Estrutura para armazenar dados agregados
    const campaigns = {};
    const allAds = [];

    // Processa cada item
    data.forEach(item => {
        if (!item) return;

        const campaignName = item.campaign_name || "";
        const adsetName = item.adset_name || "";
        const adName = item.ad_name || "";
        const spend = parseFloat(item.spend) || 0;

        // Verifica se é campanha de alcance
        const isReachCampaign = (
            campaignName.toLowerCase().includes('alcance') ||
            adsetName.toLowerCase().includes('alcance') ||
            adName.toLowerCase().includes('alcance')
        );

        // Declara leads aqui para estar disponível em todos os escopos
        let leads = 0;

        // Se for campanha de alcance, usa métricas de alcance
        if (isReachCampaign) {
            const reach = parseInt(item.reach) || 0;
            leads = reach; // Usa reach como "leads" para manter a estrutura

            if (reach > 0) {
                allAds.push({
                    campaign_name: campaignName,
                    adset_name: adsetName,
                    ad_name: adName,
                    spend: spend,
                    leads: reach,
                    cpl: spend / reach, // CPM efetivo (custo por pessoa alcançada)
                    tipo_metrica: "alcance"
                });
            }
        } else {
            // Busca por leads nas actions (lógica original)
            if (item.actions && Array.isArray(item.actions)) {
                // Primeiro tenta encontrar "lead" (mantém a lógica original)
                let leadAction = item.actions.find(action => 
                    action && action.action_type === "lead"
                );

                // Se não encontrou "lead", busca por conversões de mensagens
                if (!leadAction) {
                    // Define os tipos de conversão de mensagens aceitos
                    const messageConversionTypes = [
                        "onsite_conversion.messaging_conversation_started_7d",
                        "onsite_conversion.total_messaging_connection",
                        "onsite_conversion.messaging_first_reply"
                    ];

                    // Busca por qualquer tipo de conversão de mensagem
                    leadAction = item.actions.find(action => 
                        action && messageConversionTypes.includes(action.action_type)
                    );
                }

                // Se encontrou qualquer tipo de lead/conversão
                if (leadAction) {
                    leads = parseInt(leadAction.value) || 0;
                }
            }

            // Armazena CADA ocorrência do anúncio (não agregado)
            if (leads > 0) { // Só adiciona se tiver leads
                allAds.push({
                    campaign_name: campaignName,
                    adset_name: adsetName,
                    ad_name: adName,
                    spend: spend,
                    leads: leads,
                    cpl: spend / leads,
                    tipo_metrica: "leads"
                });
            }
        }

        // Inicializa estrutura da campanha se não existir
        if (!campaigns[campaignName]) {
            campaigns[campaignName] = {
                adsets: {},
                totalSpend: 0,
                totalLeads: 0,
                tipo_metrica: isReachCampaign ? "alcance" : "leads"
            };
        }

        // Inicializa conjunto de anúncios se não existir
        if (!campaigns[campaignName].adsets[adsetName]) {
            campaigns[campaignName].adsets[adsetName] = {
                spend: 0,
                leads: 0
            };
        }

        // Acumula valores - para alcance usa reach, para outros usa leads
        const valueToAccumulate = isReachCampaign ? (parseInt(item.reach) || 0) : leads;
        campaigns[campaignName].adsets[adsetName].spend += spend;
        campaigns[campaignName].adsets[adsetName].leads += valueToAccumulate;
        campaigns[campaignName].totalSpend += spend;
        campaigns[campaignName].totalLeads += valueToAccumulate;
    });

    // Gera array de resultados formatados
    const results = [];
    let campaignIndex = 1;

    Object.keys(campaigns).forEach(campaignName => {
        const campaign = campaigns[campaignName];
        const isReachCampaign = campaign.tipo_metrica === "alcance";

        // Adiciona header da campanha
        results.push({
            tipo: "header_campanha",
            texto: `Campanha ${campaignIndex}: ${campaignName}`
        });

        // Adiciona conjuntos de anúncios
        let adsetIndex = 1;
        Object.keys(campaign.adsets).forEach(adsetName => {
            const adset = campaign.adsets[adsetName];
            const cpl = adset.leads > 0 ? (adset.spend / adset.leads) : 0;

            if (isReachCampaign) {
                results.push({
                    tipo: "conjunto_anuncio",
                    numero: adsetIndex,
                    nome: adsetName,
                    investimento: adset.spend,
                    investimento_formatado: `R$ ${adset.spend.toFixed(2).replace('.', ',')}`,
                    alcance: adset.leads,
                    custo_por_alcance: cpl,
                    custo_por_alcance_formatado: `R$ ${cpl.toFixed(2).replace('.', ',')}`,
                    tipo_metrica: "alcance",
                    label_metrica: "pessoas_alcancadas"
                });
            } else {
                results.push({
                    tipo: "conjunto_anuncio",
                    numero: adsetIndex,
                    nome: adsetName,
                    investimento: adset.spend,
                    investimento_formatado: `R$ ${adset.spend.toFixed(2).replace('.', ',')}`,
                    leads: adset.leads,
                    custo_por_lead: cpl,
                    custo_por_lead_formatado: `R$ ${cpl.toFixed(2).replace('.', ',')}`,
                    tipo_metrica: "leads",
                    label_metrica: "leads"
                });
            }

            adsetIndex++;
        });

        // Adiciona totais
        const avgCpl = campaign.totalLeads > 0 ? (campaign.totalSpend / campaign.totalLeads) : 0;

        if (isReachCampaign) {
            results.push({
                tipo: "total",
                investimento_total: campaign.totalSpend,
                investimento_formatado: `R$ ${campaign.totalSpend.toFixed(2).replace('.', ',')}`,
                alcance_total: campaign.totalLeads,
                custo_medio_por_alcance: avgCpl,
                custo_medio_formatado: `R$ ${avgCpl.toFixed(2).replace('.', ',')}`,
                tipo_metrica: "alcance",
                label_metrica: "pessoas_alcancadas_total"
            });
        } else {
            results.push({
                tipo: "total",
                investimento_total: campaign.totalSpend,
                investimento_formatado: `R$ ${campaign.totalSpend.toFixed(2).replace('.', ',')}`,
                leads_total: campaign.totalLeads,
                custo_medio_por_lead: avgCpl,
                custo_medio_formatado: `R$ ${avgCpl.toFixed(2).replace('.', ',')}`,
                tipo_metrica: "leads",
                label_metrica: "leads_total"
            });
        }

        // Encontra melhor criativo (menor CPL entre os que têm leads)
        let bestAd = null;
        allAds.forEach(ad => {
            if (ad.campaign_name === campaignName) {
                if (!bestAd || ad.cpl < bestAd.cpl) {
                    bestAd = ad;
                }
            }
        });

        // Adiciona melhor criativo
        if (bestAd) {
            if (isReachCampaign) {
                results.push({
                    tipo: "melhor_criativo",
                    nome: bestAd.ad_name,
                    conjunto_anuncio: bestAd.adset_name,
                    alcance: bestAd.leads,
                    custo_por_alcance: bestAd.cpl,
                    custo_por_alcance_formatado: `R$ ${bestAd.cpl.toFixed(2).replace('.', ',')}`,
                    tipo_metrica: "alcance",
                    label_metrica: "pessoas_alcancadas"
                });
            } else {
                results.push({
                    tipo: "melhor_criativo",
                    nome: bestAd.ad_name,
                    conjunto_anuncio: bestAd.adset_name,
                    leads: bestAd.leads,
                    custo_por_lead: bestAd.cpl,
                    custo_por_lead_formatado: `R$ ${bestAd.cpl.toFixed(2).replace('.', ',')}`,
                    tipo_metrica: "leads",
                    label_metrica: "leads"
                });
            }
        } else {
            results.push({
                tipo: "melhor_criativo",
                mensagem: isReachCampaign ? "Nenhum criativo teve alcance" : "Nenhum criativo gerou leads"
            });
        }

        campaignIndex++;
    });

    return results;
};

