      campaignName = match[1];
      // Verifica se é campanha de alcance
      isReachCampaign = campaignName.toLowerCase().includes('alcance');
    }
  }

  // Processa apenas os conjuntos de anúncios
  const conjuntos = data.filter(item => item.tipo === "conjunto_anuncio");

  conjuntos.forEach(item => {
    const adsetName = item.nome;
